mapper.insert:
/* QueryID=kkdugi.core.menu.mapper.MenuLangMapper.insert */
INSERT INTO kkdugi_menu_lang (menu_id, lang_cd, menu_nm, menu_dc, reg_dtm, reg_id)
VALUES (#{menuId}, #{langCode}, #{label}, #{remarks}, #{createdAt}, #{creatorId})

mapper.update:
/* QueryID=kkdugi.core.menu.mapper.MenuLangMapper.update */
UPDATE kkdugi_menu_lang
SET menu_nm = #{label},
    menu_dc = #{remarks},
    upd_dtm = #{updatedAt},
    upd_id  = #{updaterId}
WHERE menu_id = #{menuId} AND lang_cd = #{langCode}

